const listTurns = `-- name: ListTurns :many
select id, session_id, seq, state, text, created_at, ended_at, token_hash, stop_reason, dispatched_at, total_tokens, input_tokens, output_tokens, thought_tokens, cached_read_tokens, cached_write_tokens, cancel_requested_at, failure_reason, failure_message, started_at, runner_id, created_by from turns where session_id = $1 and seq < $2 order by seq desc limit $3
`

type ListTurnsParams struct {
	SessionID uuid.UUID
	Before    int32
	Count     int32
}

// The turns of a session that came before the one with the sequence number
// @before, newest first.
func (q *Queries) ListTurns(ctx context.Context, arg ListTurnsParams) ([]Turn, error) {
	rows, err := q.db.Query(ctx, listTurns, arg.SessionID, arg.Before, arg.Count)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Turn
	for rows.Next() {
		var i Turn
		if err := rows.Scan(
			&i.ID,
			&i.SessionID,
			&i.Seq,
			&i.State,
			&i.Text,
			&i.CreatedAt,
			&i.EndedAt,
			&i.TokenHash,
			&i.StopReason,
			&i.DispatchedAt,
			&i.TotalTokens,
			&i.InputTokens,
			&i.OutputTokens,
			&i.ThoughtTokens,
			&i.CachedReadTokens,
			&i.CachedWriteTokens,
			&i.CancelRequestedAt,
			&i.FailureReason,
			&i.FailureMessage,
			&i.StartedAt,
			&i.RunnerID,
			&i.CreatedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lock = `-- name: Lock :exec
select pg_advisory_xact_lock($1)
`

// Waits for the advisory lock of the key and holds it until the transaction
// ends.
func (q *Queries) Lock(ctx context.Context, key int64) error {
	_, err := q.db.Exec(ctx, lock, key)
	return err
}

const nextTurns = `-- name: NextTurns :many
select turns.id as turn_id, sessions.id as session_id, agents.id as agent_id, agents.project_id, agents.harness,
       agents.resources, agents.approval, coalesce(providers.url, '')::text as provider_url, agents.model,
       extract(epoch from now() - turns.created_at)::float8 as waited
from turns
join sessions on sessions.id = turns.session_id
join agents on agents.id = sessions.agent_id
left join providers on providers.id = agents.provider_id
where turns.state = 'queued'
order by turns.created_at, turns.id
limit greatest($1::bigint - (select count(*) from turns where state in ('dispatching', 'running')), 0)
`

type NextTurnsRow struct {
	TurnID      uuid.UUID
	SessionID   uuid.UUID
	AgentID     uuid.UUID
	ProjectID   uuid.UUID
	Harness     string
	Resources   []byte
	Approval    string
	ProviderUrl string
	Model       string
	Waited      float64
}

// The queued turns that there is room to run, oldest first. A turn of an
// agent that names its model has the URL of the agent's provider and the
// name of the model.
func (q *Queries) NextTurns(ctx context.Context, maxRunning int64) ([]NextTurnsRow, error) {
	rows, err := q.db.Query(ctx, nextTurns, maxRunning)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []NextTurnsRow
	for rows.Next() {
		var i NextTurnsRow
		if err := rows.Scan(
			&i.TurnID,
			&i.SessionID,
			&i.AgentID,
			&i.ProjectID,
			&i.Harness,
			&i.Resources,
			&i.Approval,
			&i.ProviderUrl,
			&i.Model,
			&i.Waited,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

